package com.knowflow.learning.adaptive;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import com.knowflow.exception.BusinessException;import com.knowflow.learning.evidence.*;import com.knowflow.learning.feedback.*;import com.knowflow.learning.privatequiz.PrivateQuizService;import com.knowflow.learning.tutor.*;import com.knowflow.service.KnowledgeMasteryService;import lombok.RequiredArgsConstructor;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import java.time.*;import java.sql.Timestamp;import java.util.*;import java.util.function.Supplier;
/** Read projection of original records. Does not capture/regrade evidence or calculate NextAction. */
@Service @RequiredArgsConstructor @ConditionalOnProperty(name={"knowflow.product.adaptive-learning.enabled","knowflow.product.interview-learning.enabled","knowflow.product.private-quiz.enabled","knowflow.product.tutor.enabled","knowflow.product.tutor-coaching.enabled"},havingValue="true")
public class EvidenceReportService {
 private final JdbcTemplate sql;private final ObjectMapper json;private final LearningEvidenceService evidence;private final LearningEvidenceSources scope;private final PrivateQuizService quizzes;private final TutorAssessmentService assessments;private final TutorMicroService micros;private final ErrorAnnotationService annotations;private final InterviewRetestService retests;private final QuestionVariantService variants;private final InterleavedPracticeService interleaved;private final FeedbackSourceService sources;private final KnowledgeMasteryService mastery;private final com.knowflow.interview.v2.InterviewV2Service interviews;
 private long n(Map<String,Object> r,String k){return ((Number)r.get(k)).longValue();}
 private record Item(String kind,long id,String at,List<Long> knowledgeIds,String association,Map<String,Object> original){}
 private record Query(String kind,String query,java.util.function.Function<Map<String,Object>,Map<String,Object>> load){}
 private void add(List<Item> out,List<String> unavailable,String kind,long id,Object at,List<Long> kids,String association,Supplier<Map<String,Object>> load,long user){try{for(long k:kids)scope.requireKnowledge(k,user);out.add(new Item(kind,id,Objects.toString(at,"UNKNOWN"),kids,association,load.get()));}catch(BusinessException e){if(!Set.of(403,404,409).contains(e.getCode()))throw e;unavailable.add(kind+":"+id);}}
 private List<Long> mapped(long user,String type,long id){var ids=sql.queryForList("SELECT knowledge_id FROM resource_knowledge_mapping WHERE resource_type=? AND resource_id=? AND deleted=0 AND source='MANUAL' AND status='ACCEPTED'",Long.class,type,id);var out=new ArrayList<Long>();for(long k:ids){try{scope.requireKnowledge(k,user);out.add(k);}catch(BusinessException e){if(!Set.of(403,404,409).contains(e.getCode()))throw e;}}return List.copyOf(out);}
 private List<Long> annotationKnowledge(long u,long id){return mapped(u,"ERROR_ANNOTATION",id);}
 private List<Long> sourceKnowledge(long u,String type,long id){if("TUTOR_ASSESSMENT".equals(type)){var ids=sql.queryForList("SELECT knowledge_id FROM tutor_assessment WHERE id=? AND owner_id=? AND knowledge_id IS NOT NULL",Long.class,id,u);return List.copyOf(ids);}var result=new LinkedHashSet<Long>();for(long annotation:sql.queryForList("SELECT id FROM learning_error_annotation WHERE owner_id=? AND source_type=? AND source_id=?",Long.class,u,type,id))result.addAll(annotationKnowledge(u,annotation));return List.copyOf(result);}
 public Map<String,Object> report(long u,Long filter){if(filter!=null){if(filter<1)throw new BusinessException(400,"知识点编号无效");scope.requireKnowledge(filter,u);}var from=Timestamp.from(Instant.now().minus(Duration.ofDays(7)));var until=Instant.now();var items=new ArrayList<Item>();var unavailable=new ArrayList<String>();var bounds=new LinkedHashMap<String,Boolean>();
  // T02 frozen receipts remain untouched. Current comparison checks are delegated to the original service below.
  var receiptRows=sql.queryForList("SELECT source_type,source_id,occurred_at FROM learning_evidence_receipt WHERE user_id=? AND occurred_at>=? ORDER BY occurred_at DESC LIMIT 101",u,from);bounds.put("T02_RECEIPT",receiptRows.size()>100);for(var r:receiptRows.stream().limit(100).toList()){String type=r.get("source_type").toString();long id=n(r,"source_id");add(items,unavailable,"T02_"+type,id,r.get("occurred_at"),List.of(),"FROZEN_T02",()->{if(type.equals("INTERVIEW_TURN"))sources.read(u,type,id,0);return evidence.get(u,type,id);},u);}
  var queries=List.of(
   new Query("PRIVATE_ATTEMPT","SELECT id,submitted_at AS at FROM private_quiz_attempt WHERE owner_id=? AND state='SUBMITTED' AND submitted_at>=? ORDER BY submitted_at DESC LIMIT 101",r->{sources.read(u,"PRIVATE_ATTEMPT",n(r,"id"),0);return quizzes.getAttempt(u,n(r,"id"));}),
   new Query("TEACH_BACK","SELECT id,conversation_id,evaluated_at AS at FROM tutor_assessment WHERE owner_id=? AND state='SUCCEEDED' AND evaluated_at>=? ORDER BY evaluated_at DESC LIMIT 101",r->{long id=n(r,"id");sources.read(u,"TUTOR_ASSESSMENT",id,0);return assessments.list(n(r,"conversation_id"),u).stream().filter(a->n(a,"id")==id).findFirst().orElseThrow(()->new BusinessException(404,"复述来源不存在"));}),
   new Query("MICRO_CHALLENGE","SELECT id,completed_at AS at FROM tutor_micro_session WHERE owner_id=? AND state='COMPLETED' AND completed_at>=? ORDER BY completed_at DESC LIMIT 101",r->micros.detail(n(r,"id"),u)),
   new Query("ERROR_ANNOTATION","SELECT id,updated_at AS at FROM learning_error_annotation WHERE owner_id=? AND state='SUCCEEDED' AND updated_at>=? ORDER BY updated_at DESC LIMIT 101",r->annotations.detail(n(r,"id"),u)),
   new Query("QUESTION_VARIANT","SELECT id,created_at AS at FROM learning_question_variant WHERE owner_id=? AND state='SAVED' AND created_at>=? ORDER BY created_at DESC LIMIT 101",r->variants.detail(u,n(r,"id"))),
   new Query("INTERVIEW_RETEST","SELECT p.id,COALESCE((SELECT MAX(h.created_at) FROM learning_interview_retest_history h WHERE h.plan_id=p.id AND h.owner_id=p.owner_id),p.created_at) AS at FROM learning_interview_retest p WHERE p.owner_id=? AND (p.created_at>=? OR EXISTS(SELECT 1 FROM learning_interview_retest_history h WHERE h.plan_id=p.id AND h.owner_id=p.owner_id AND h.created_at>=?)) ORDER BY at DESC LIMIT 101",r->retests.detail(u,n(r,"id"))),
   new Query("MOCK_INTERVIEW","SELECT v.session_id AS id,v.updated_at AS at FROM mock_interview_v2_state v JOIN interview_radar_session_binding b ON b.session_id=v.session_id AND b.user_id=v.user_id WHERE v.user_id=? AND b.stage='MOCK' AND v.state='COMPLETED' AND v.updated_at>=? ORDER BY v.updated_at DESC LIMIT 101",r->{long sid=n(r,"id");for(long tid:sql.queryForList("SELECT id FROM mock_interview_v2_turn WHERE session_id=? AND user_id=?",Long.class,sid,u))sources.read(u,"INTERVIEW_TURN",tid,0);return interviews.get(u,sid);}),
   new Query("INTERLEAVED","SELECT id,completed_at AS at FROM interleaved_session WHERE owner_id=? AND state='COMPLETED' AND completed_at>=? ORDER BY completed_at DESC LIMIT 101",r->interleaved.get(u,n(r,"id")))
  );
  for(var q:queries){var rows=q.kind().equals("INTERVIEW_RETEST")?sql.queryForList(q.query(),u,from,from):sql.queryForList(q.query(),u,from);bounds.put(q.kind(),rows.size()>100);for(var r:rows.stream().limit(100).toList())add(items,unavailable,q.kind(),n(r,"id"),r.get("at"),List.of(),"ORIGINAL_RECORD",()->q.load().apply(r),u);}
  // Resolve only explicit identities. A session's manual topic association never rewrites T02 or Mastery.
  var resolved=new ArrayList<Item>();for(var item:items){var kids=new LinkedHashSet<Long>();var data=item.original();if(item.kind().startsWith("T02_")){var raw=data.get("knowledgeIds");if(raw instanceof List<?> ids)for(var id:ids)if(id instanceof Number number)kids.add(number.longValue());if(item.kind().equals("T02_INTERVIEW_TURN"))kids.addAll(sourceKnowledge(u,"INTERVIEW_TURN",item.id()));}
   if(item.kind().equals("ERROR_ANNOTATION"))kids.addAll(annotationKnowledge(u,item.id()));
   if(item.kind().equals("TEACH_BACK")&&data.get("knowledgeId") instanceof Number k)kids.add(k.longValue());
   if(item.kind().equals("PRIVATE_ATTEMPT")){kids.addAll(sourceKnowledge(u,"PRIVATE_ATTEMPT",item.id()));for(var session:sql.queryForList("SELECT refs_json FROM interleaved_session WHERE owner_id=? AND state='COMPLETED' ORDER BY id DESC LIMIT 100",u)){try{var refs=json.readTree(session.get("refs_json").toString());for(var ref:refs)if(ref.path("attemptId").asLong()==item.id())kids.add(ref.path("knowledgeId").asLong());}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new BusinessException(500,"交错来源记录损坏");}}}
   if(item.kind().equals("MICRO_CHALLENGE")&&data.get("assessmentId") instanceof Number a)kids.addAll(sourceKnowledge(u,"TUTOR_ASSESSMENT",a.longValue()));
   if(item.kind().equals("INTERVIEW_RETEST")&&data.get("baselineTurn") instanceof Number b)kids.addAll(sourceKnowledge(u,"INTERVIEW_TURN",b.longValue()));
   if(item.kind().equals("QUESTION_VARIANT"))kids.addAll(sourceKnowledge(u,data.get("sourceType").toString(),((Number)data.get("sourceId")).longValue()));
   if(item.kind().equals("INTERLEAVED")){var tree=json.valueToTree(data.get("items"));for(var ref:tree)kids.add(ref.path("knowledgeId").asLong());}
   boolean accessible=true;for(long k:kids)try{scope.requireKnowledge(k,u);}catch(BusinessException e){if(!Set.of(403,404,409).contains(e.getCode()))throw e;accessible=false;}if(!accessible){unavailable.add(item.kind()+":"+item.id());continue;}if(filter==null||kids.contains(filter))resolved.add(new Item(item.kind(),item.id(),item.at(),List.copyOf(kids),kids.isEmpty()?"UNKNOWN":"EXPLICIT_IDENTITY_READ_PROJECTION",data));
  }
  resolved.sort(Comparator.comparing(Item::at).reversed());var counts=new LinkedHashMap<String,Long>();for(var i:resolved)counts.merge(i.kind(),1L,Long::sum);var masteries=new ArrayList<Object>();if(filter!=null)masteries.add(mastery.getDetail(u,filter));else for(var m:mastery.listAll(u).stream().limit(100).toList())try{scope.requireKnowledge(m.getKnowledgeId(),u);masteries.add(mastery.getDetail(u,m.getKnowledgeId()));}catch(BusinessException e){if(!Set.of(403,404,409).contains(e.getCode()))throw e;}
  return Map.ofEntries(Map.entry("from",from.toInstant().toString()),Map.entry("until",until.toString()),Map.entry("days",7),Map.entry("items",resolved),Map.entry("counts",counts),Map.entry("boundedByKind",bounds),Map.entry("unavailableCount",unavailable.size()),Map.entry("mastery",masteries),Map.entry("firstAttemptRef","UNKNOWN_UNLESS_ORIGINAL_T02_PROVES_IT"),Map.entry("semantics","READ_ONLY_LAST_7_DAYS_MAX_100_PER_KIND;COUNTS_OVERLAP_NOT_UNIQUE_ACTIVITIES;MASTERY_CURRENT_SNAPSHOT;NO_REGRADING;NO_IMPROVEMENT_PERCENT"));
 }
}
